package com.andye.warmod.rocket;import com.andye.warmod.WarMod;import com.andye.warmod.entity.RocketProjectileEntity;import com.andye.warmod.testtool.TestExplosionService;import com.andye.warmod.warhead.WarheadImpactService;import java.util.UUID;import net.minecraft.SharedConstants;import net.minecraft.core.BlockPos;import net.minecraft.core.particles.ParticleTypes;import net.minecraft.server.level.ServerLevel;import net.minecraft.server.level.ServerPlayer;import net.minecraft.sounds.SoundEvents;import net.minecraft.sounds.SoundSource;import net.minecraft.world.phys.Vec3;public final class RocketImpactService {private RocketImpactService(){}public static void impact(ServerLevel level,RocketProjectileEntity rocket,Vec3 position){ServerPlayer owner=rocket.ownerId()==null?null:level.getServer().getPlayerList().getPlayer(rocket.ownerId());if(owner!=null&&owner.level()!=level)owner=null;if(rocket.payloadType()==RocketPayloadType.HE){WarheadImpactService.detonateTacticalHe(level,owner,rocket.getUUID(),position,rocket.visualSeed());}else{UUID id=rocket.getUUID();WarheadImpactService.detonateAt(level,owner,id,id,position,rocket.visualSeed(),rocket.payloadType().warhead(),false);}if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("Rocket {} impacted: payload={}, position={}",rocket.getUUID(),rocket.payloadType(),position);}}